<?php
require_once 'php/bootstrap.php'; require_role('administrator');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);
if($action==='approve_payment'){$q=$pdo->prepare('UPDATE payments SET status="paid",verified_by=? WHERE id=? AND status="pending"');$q->execute([current_user()['id'],$id]);flash('Payment approved; student is now eligible to book.');}
elseif($action==='reject_payment'){$pdo->prepare('UPDATE payments SET status="rejected",verified_by=? WHERE id=?')->execute([current_user()['id'],$id]);flash('Payment rejected.');}
elseif($action==='complete_booking'){$pdo->prepare('UPDATE bookings SET status="completed" WHERE id=?')->execute([$id]);flash('Session marked completed.');}
elseif($action==='add_programme'){$name=trim($_POST['name']??'');$fee=(float)($_POST['fee']??0);if($name && $fee>=0){$pdo->prepare('INSERT INTO programmes(name,fee,active) VALUES(?,?,1)')->execute([$name,$fee]);flash('Programme added.');}}
redirect('admin.php');}
page_start('Administrator dashboard');
$payments=$pdo->query('SELECT pay.*,u.full_name,pr.name programme FROM payments pay JOIN users u ON u.id=pay.student_id JOIN programmes pr ON pr.id=pay.programme_id ORDER BY pay.id DESC')->fetchAll();
?>
<section class="card"><h2>Payment verification</h2><div class="table-wrap"><table><tr><th>Student</th><th>Programme</th><th>Amount</th><th>Status</th><th>Action</th></tr><?php foreach($payments as $p): ?><tr><td><?=e($p['full_name'])?></td><td><?=e($p['programme'])?></td><td>R<?=number_format((float)$p['amount'],2)?></td><td><?=e($p['status'])?></td><td><?php if($p['status']==='pending'): ?><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$p['id']?>"><button name="action" value="approve_payment">Approve</button><button class="danger" name="action" value="reject_payment">Reject</button></form><?php endif ?></td></tr><?php endforeach ?></table></div></section>
<section class="card"><h2>Add programme</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_programme"><label>Programme name<input name="name" required></label><label>Fee (R)<input type="number" name="fee" min="0" step="0.01" required></label><button>Add programme</button></form></section>
<section class="card"><h2>Users</h2><?php $users=$pdo->query('SELECT id,full_name,email,role,created_at FROM users ORDER BY id DESC')->fetchAll(); ?><div class="table-wrap"><table><tr><th>Name</th><th>Email</th><th>Role</th><th>Created</th></tr><?php foreach($users as $u): ?><tr><td><?=e($u['full_name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td><td><?=e($u['created_at'])?></td></tr><?php endforeach ?></table></div></section>
<section class="card"><h2>Bookings</h2><?php $bs=$pdo->query('SELECT b.*,s.full_name student,t.full_name tutor,p.name programme FROM bookings b JOIN users s ON s.id=b.student_id LEFT JOIN users t ON t.id=b.tutor_id JOIN programmes p ON p.id=b.programme_id ORDER BY b.session_date DESC')->fetchAll(); ?><div class="table-wrap"><table><tr><th>Date</th><th>Time</th><th>Student</th><th>Tutor</th><th>Programme</th><th>Status</th><th></th></tr><?php foreach($bs as $b): ?><tr><td><?=e($b['session_date'])?></td><td><?=e($b['start_time'])?></td><td><?=e($b['student'])?></td><td><?=e($b['tutor']??'Unassigned')?></td><td><?=e($b['programme'])?></td><td><?=e($b['status'])?></td><td><?php if($b['status']==='confirmed'): ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$b['id']?>"><button name="action" value="complete_booking">Complete</button></form><?php endif ?></td></tr><?php endforeach ?></table></div></section>
<?php page_end(); ?>
